import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../lib/AuthContext'
import { supabase } from '../lib/supabase'

export default function InboxScreen({ onSwitchClient }) {
  const { session, sessionList, switchClient, logout } = useAuth()
  const navigate = useNavigate()
  const [conversations, setConversations] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [showSearch, setShowSearch] = useState(false)
  const [searchResults, setSearchResults] = useState([])
  const [searching, setSearching] = useState(false)

  const myUsername = session.client.username

  useEffect(() => { loadConversations() }, [session])

  async function loadConversations() {
    setLoading(true)
    try {
      const { data } = await supabase
        .from('conversations')
        .select('*')
        .not('convo_key', 'is', null)
        .ilike('convo_key', `%${myUsername}%`)
        .order('last_message_at', { ascending: false, nullsFirst: false })
      const convos = (data || []).map(c => {
        const parts = c.convo_key.split('::')
        const otherUsername = parts.find(p => p !== myUsername) || parts[0]
        return { ...c, otherUsername }
      })
      setConversations(convos)
    } catch(e) { console.error(e) }
    setLoading(false)
  }

  useEffect(() => {
    async function doSearch() {
      if (!search.trim()) { setSearchResults([]); return }
      setSearching(true)
      try {
        const { data } = await supabase
          .from('clients')
          .select('id, username, full_name')
          .ilike('username', `%${search}%`)
          .eq('status', 'active')
          .neq('username', myUsername)
          .limit(8)
        setSearchResults(data || [])
      } catch(e) { console.error(e) }
      setSearching(false)
    }
    const timer = setTimeout(doSearch, 300)
    return () => clearTimeout(timer)
  }, [search, session])

  const permLabel = { read_send:'read + send', read_only:'read only', send_only:'send only' }
  const initials = (str) => str ? str.slice(0,2).toUpperCase() : '??'
  const avatarColors = [['#2a1f05','#F5C518'],['#1a1f2e','#85b7eb'],['#1e2a1e','#5dcaa5'],['#2a1a1e','#d85a30'],['#221a2e','#d4537e']]
  const colorFor = (str) => avatarColors[(str||'').charCodeAt(0) % avatarColors.length]

  function timeAgo(ts) {
    if (!ts) return ''
    const diff = Date.now() - new Date(ts)
    const m = Math.floor(diff / 60000)
    if (m < 1) return 'just now'
    if (m < 60) return `${m}m`
    const h = Math.floor(m / 60)
    if (h < 24) return `${h}h`
    return 'yesterday'
  }

  function openChat(username) {
    setShowSearch(false); setSearch(''); setSearchResults([])
    navigate(`/chat/${username}`)
  }

  const multiClient = sessionList.length > 1
  const neu = { shadow: '6px 6px 12px #12141c, -3px -3px 8px #252528' }

  return (
    <div style={s.wrap}>
      <div style={s.topBar}>
        <div style={s.userPill} onClick={() => multiClient && navigate('/select')}>
          <div style={s.avatar}>{initials(myUsername)}</div>
          <div>
            <div style={s.handle}>@{myUsername}</div>
            <div style={s.subHandle}>{session.user.full_name} · {permLabel[session.permission]}</div>
          </div>
          {multiClient && <span style={s.switchBadge}>{sessionList.length} ▾</span>}
        </div>
        <button style={s.searchIconBtn} onClick={() => setShowSearch(true)}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#888aa0" strokeWidth="2" strokeLinecap="round">
            <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
          </svg>
        </button>
      </div>

      {showSearch && (
        <div style={s.searchOverlay}>
          <div style={s.searchRow}>
            <div style={{ ...s.searchBar, boxShadow: neu.shadow }}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#F5C518" strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
              <input autoFocus style={s.searchInput} placeholder="find a username..."
                value={search} onChange={e => setSearch(e.target.value)} />
            </div>
            <button style={s.cancelBtn} onClick={() => { setShowSearch(false); setSearch(''); setSearchResults([]) }}>cancel</button>
          </div>
          <div style={s.searchResults}>
            {!search.trim() && <div style={s.searchHint}>start typing to find someone</div>}
            {searching && <div style={s.searchHint}>searching...</div>}
            {!searching && search.trim() && searchResults.length === 0 && (
              <div style={s.searchHint}>no users found for "{search}"</div>
            )}
            {searchResults.map(client => {
              const [bg, fg] = colorFor(client.username)
              return (
                <div key={client.id} style={s.resultItem} onClick={() => openChat(client.username)}>
                  <div style={{ ...s.resultAvatar, background:bg, color:fg }}>{initials(client.username)}</div>
                  <div>
                    <div style={s.resultName}>{client.full_name}</div>
                    <div style={s.resultHandle}>@{client.username}</div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {!showSearch && (
        <>
          <div style={s.sectionLabel}>my conversations</div>
          <div style={s.list}>
            {loading && <div style={s.empty}>loading...</div>}
            {!loading && conversations.length === 0 && (
              <div style={s.empty}>
                <div style={s.emptyIcon}>💬</div>
                <div>no conversations yet</div>
                <div style={s.emptyAction} onClick={() => setShowSearch(true)}>tap search to find someone →</div>
              </div>
            )}
            {conversations.map(convo => {
              const [bg, fg] = colorFor(convo.otherUsername)
              return (
                <div key={convo.id} style={{ ...s.convoItem, boxShadow: neu.shadow }} onClick={() => navigate(`/chat/${convo.otherUsername}`)}>
                  <div style={{ ...s.convoAvatar, background:bg, color:fg }}>{initials(convo.otherUsername)}</div>
                  <div style={s.convoInfo}>
                    <div style={s.convoName}>@{convo.otherUsername}</div>
                    <div style={s.convoPreview}>{convo.last_message || 'no messages yet'}</div>
                  </div>
                  <div style={s.convoMeta}>
                    <div style={s.convoTime}>{timeAgo(convo.last_message_at)}</div>
                    {convo.unread_count > 0 && <div style={s.badge}>{convo.unread_count}</div>}
                  </div>
                </div>
              )
            })}
          </div>
        </>
      )}

      <div style={s.bottomNav}>
        <button style={{...s.navBtn, color:'#F5C518'}}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#F5C518" strokeWidth="2" strokeLinecap="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          <span style={s.navLabel}>chats</span>
        </button>
        {multiClient && (
          <button style={s.navBtn} onClick={() => navigate('/select')}>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#888aa0" strokeWidth="2" strokeLinecap="round"><path d="M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/></svg>
            <span style={s.navLabel}>clients</span>
          </button>
        )}
        <button style={s.navBtn} onClick={logout}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#888aa0" strokeWidth="2" strokeLinecap="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/></svg>
          <span style={s.navLabel}>logout</span>
        </button>
      </div>
    </div>
  )
}

const s = {
  wrap: { background:'#111114', minHeight:'100vh', display:'flex', flexDirection:'column', fontFamily:"'Clarity City','DM Mono',sans-serif", color:'#ffffff', maxWidth:480, margin:'0 auto' },
  topBar: { padding:'18px 20px 14px', display:'flex', alignItems:'center', justifyContent:'space-between', borderBottom:'0.5px solid #252528', flexShrink:0 },
  userPill: { display:'flex', alignItems:'center', gap:12, cursor:'pointer' },
  avatar: { width:42, height:42, borderRadius:12, background:'#2a1f05', display:'flex', alignItems:'center', justifyContent:'center', fontSize:16, fontWeight:700, color:'#F5C518' },
  handle: { fontSize:18, fontWeight:700, color:'#ffffff' },
  subHandle: { fontSize:12, color:'#888aa0', fontFamily:"'DM Mono',monospace", marginTop:2 },
  switchBadge: { fontSize:12, color:'#F5C518', fontFamily:"'DM Mono',monospace", background:'#2a1f05', border:'0.5px solid #F5C51840', padding:'2px 8px', borderRadius:6, marginLeft:4 },
  searchIconBtn: { background:'none', border:'none', cursor:'pointer', padding:4, display:'flex' },
  searchOverlay: { flex:1, display:'flex', flexDirection:'column', background:'#111114' },
  searchRow: { padding:'16px 20px', display:'flex', alignItems:'center', gap:12, borderBottom:'0.5px solid #252528' },
  searchBar: { flex:1, background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:14, display:'flex', alignItems:'center', gap:10, padding:'12px 16px' },
  searchInput: { background:'none', border:'none', outline:'none', color:'#ffffff', fontSize:16, fontFamily:"'Clarity City','DM Mono',sans-serif", width:'100%' },
  cancelBtn: { background:'none', border:'none', color:'#F5C518', fontSize:14, cursor:'pointer', fontFamily:"'Clarity City','DM Mono',sans-serif", whiteSpace:'nowrap' },
  searchResults: { flex:1, padding:'8px 0', overflowY:'auto' },
  searchHint: { textAlign:'center', padding:'40px 16px', color:'#444', fontSize:14, fontFamily:"'DM Mono',monospace" },
  resultItem: { display:'flex', alignItems:'center', gap:14, padding:'14px 20px', cursor:'pointer', borderBottom:'0.5px solid #1a1a1e' },
  resultAvatar: { width:48, height:48, borderRadius:12, fontSize:16, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 },
  resultName: { fontSize:16, fontWeight:600, color:'#ffffff' },
  resultHandle: { fontSize:13, color:'#888aa0', fontFamily:"'DM Mono',monospace", marginTop:2 },
  sectionLabel: { fontSize:11, fontWeight:600, letterSpacing:'0.14em', color:'#888aa0', textTransform:'uppercase', fontFamily:"'DM Mono',monospace", padding:'20px 20px 10px', flexShrink:0 },
  list: { flex:1, overflowY:'auto', padding:'0 20px', display:'flex', flexDirection:'column', gap:12, paddingBottom:20 },
  empty: { textAlign:'center', padding:'60px 16px', color:'#444', fontSize:14, fontFamily:"'DM Mono',monospace", lineHeight:2.5 },
  emptyIcon: { fontSize:40, marginBottom:12 },
  emptyAction: { color:'#F5C518', cursor:'pointer', fontSize:13 },
  convoItem: { background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:16, padding:'16px', display:'flex', alignItems:'center', gap:14, cursor:'pointer' },
  convoAvatar: { width:48, height:48, borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center', fontSize:16, fontWeight:700, flexShrink:0 },
  convoInfo: { flex:1, minWidth:0 },
  convoName: { fontSize:17, fontWeight:700, marginBottom:4, color:'#ffffff' },
  convoPreview: { fontSize:14, color:'#888aa0', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis', fontFamily:"'DM Mono',monospace" },
  convoMeta: { textAlign:'right', flexShrink:0 },
  convoTime: { fontSize:12, color:'#444', fontFamily:"'DM Mono',monospace", marginBottom:4 },
  badge: { background:'#F5C518', color:'#111114', fontSize:11, fontWeight:700, borderRadius:10, padding:'2px 8px', fontFamily:"'DM Mono',monospace", display:'inline-block' },
  bottomNav: { borderTop:'0.5px solid #252528', display:'flex', padding:'12px 0 20px', flexShrink:0 },
  navBtn: { flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:5, background:'none', border:'none', cursor:'pointer', color:'#888aa0' },
  navLabel: { fontSize:11, fontFamily:"'DM Mono',monospace" }
}
